-- Расширение каталога рецептов до 30 блюд (18 в 0003 + 12 здесь).
-- Строки добавляются только если рецепта с таким названием ещё нет в каталоге,
-- поэтому миграция идемпотентна и безопасна для повторного применения.
insert into recipes (user_id, title, time_label, ingredients, instructions, image, kcal, protein, fat, carbs)
select * from (values
  (null::text, 'Плов с курицей', '60 мин', 'рис, курица, морковь, лук, чеснок', 'Обжарьте курицу с луком и морковью, добавьте промытый рис и воду, тушите под крышкой 40 минут.', '/images/coock.jpg', 380, 24, 10, 48),
  (null, 'Салат «Греческий»', '15 мин', 'помидор, огурец, перец, сыр, масло', 'Нарежьте овощи крупными кубиками, добавьте сыр, заправьте маслом и лимонным соком.', '/images/hero-tomatoes.jpg', 170, 6, 13, 8),
  (null, 'Лечо из перца', '45 мин', 'перец, помидор, лук, морковь, сахар', 'Тушите перец с томатами и пассерованными овощами 30 минут, добавьте специи по вкусу.', '/images/paprika.jpg', 120, 3, 4, 18),
  (null, 'Сырники со сметаной', '30 мин', 'творог, яйца, мука, сахар', 'Смешайте творог с яйцами и мукой, сформируйте сырники и обжарьте с двух сторон до золотистой корочки.', '/images/whisk-bowl.jpg', 310, 17, 12, 32),
  (null, 'Куриный бульон с сухариками', '50 мин', 'курица, морковь, лук, хлеб', 'Отварите курицу с овощами, процедите бульон, подавайте с подсушенными сухариками.', '/images/soup-cup.jpg', 140, 12, 5, 10),
  (null, 'Картофельное пюре', '25 мин', 'картофель, молоко, масло', 'Отварите картофель до мягкости, разомните с горячим молоком и сливочным маслом.', '/images/kasha.jpg', 210, 5, 9, 28),
  (null, 'Тосты с авокадо и яйцом', '10 мин', 'хлеб, авокадо, яйца, лимон', 'Поджарьте хлеб, намажьте размятым авокадо с лимоном, сверху выложите яйцо пашот.', '/images/bread.jpg', 290, 11, 17, 22),
  (null, 'Рис с овощами', '30 мин', 'рис, морковь, перец, горошек, масло', 'Отварите рис, обжарьте овощи на сковороде, соедините и прогрейте пару минут.', '/images/ragu.jpg', 260, 6, 7, 44),
  (null, 'Запечённые яблоки с мёдом', '35 мин', 'яблоко, мёд, орехи, корица', 'Вырежьте сердцевину яблок, наполните орехами с мёдом и корицей, запекайте 25 минут при 180°.', '/images/zapekanka.jpg', 150, 2, 4, 28),
  (null, 'Яичный рулет с сыром', '20 мин', 'яйца, сыр, молоко, зелень', 'Взбейте яйца с молоком, испеките тонкий омлет, посыпьте тёртым сыром и сверните рулетом.', '/images/omlet.jpg', 270, 19, 19, 5),
  (null, 'Грибной крем-суп', '40 мин', 'грибы, картофель, сливки, лук', 'Отварите грибы с картофелем и луком, пробейте блендером, добавьте сливки и прогрейте.', '/images/green-spoon.jpg', 190, 6, 11, 17),
  (null, 'Макароны по-флотски', '35 мин', 'макароны, фарш, лук, масло', 'Обжарьте фарш с луком до готовности, смешайте с отварными макаронами, прогрейте.', '/images/pasta.jpg', 440, 21, 16, 52)
) as v(user_id, title, time_label, ingredients, instructions, image, kcal, protein, fat, carbs)
where not exists (
  select 1 from recipes r where r.user_id is null and r.title = v.title
);
